INSERT INTO "PUBLIC"."PROFILES" VALUES
('b0000000-0000-4000-8000-000000000001', 27, 'Backend dev at a bank by day, side-project builder by night. I make a solid filter coffee and a terrible first impression on video calls.', 'MALE', 'Thane, Maharashtra', 'Hardik Arora', TIMESTAMP '2026-10-04 09:30:00', 'a0000000-0000-4000-8000-000000000001', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'NON_VEG', 'QUALITY_TIME', 'MAYBE', 'NIGHT_OWL', 'NO', 'Tell me your most underrated opinion.', U&'{"id": "talk_about", "question": "A random thing I could talk about for hours is\2026", "answer": "Why the Mumbai local is the best-designed system in India."}', U&'{"id": "weekend", "question": "My weekend reset looks like\2026", "answer": "A Yeoor hills walk, a long breakfast, then pretending I''ll finish my side project."}', U&'{"id": "green_flag", "question": "A green flag I never ignore is\2026", "answer": "Someone who replies to the actual message, not just the last line."}', 19.2183, 72.9781),
('b0000000-0000-4000-8000-000000000002', 25, 'Content strategist in Delhi. Collector of playlists, bad puns and window seats. Will judge your chai order (lovingly).', 'FEMALE', 'Delhi', 'Upasana Rai', TIMESTAMP '2026-10-05 09:30:00', 'a0000000-0000-4000-8000-000000000002', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'NON_VEG', 'WORDS_OF_AFFIRMATION', 'NO', 'NIGHT_OWL', 'NO', 'Start sweet, start funny, start however you like.', U&'{"id": "simple_joy", "question": "My simple joy is\2026", "answer": "A cutting chai at Carter Road when the sea is being dramatic."}', U&'{"id": "secretly_love", "question": "I secretly love\2026", "answer": "90s Bollywood songs at full volume while cooking."}', U&'{"id": "feel_loved", "question": "The way I feel loved is\2026", "answer": "Voice notes. Long ones. With background noise."}', 19.0596, 72.8295),
('b0000000-0000-4000-8000-000000000003', 28, 'Chartered accountant who reads thrillers to cope with spreadsheets. Weekend baker. Strong opinions about pav bhaji.', 'FEMALE', 'Thane, Maharashtra', 'Rakshita Singhal', TIMESTAMP '2026-10-06 09:30:00', 'a0000000-0000-4000-8000-000000000003', 'CALLS_OVER_TEXTS', 'TAKE_SPACE_FIRST', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'NO', 'VEG', 'ACTS_OF_SERVICE', 'MAYBE', 'EARLY_BIRD', 'NO', 'Come with a good joke or a better playlist.', U&'{"id": "comfort", "question": "My comfort habit is\2026", "answer": "Rereading the last chapter of a book I already finished."}', U&'{"id": "value_people", "question": "I value people who\2026", "answer": "Show up on time and remember the small things."}', U&'{"id": "getting_better", "question": "Something I am trying to get better at is\2026", "answer": "Sourdough. It''s currently winning."}', 19.1975, 72.9706),
('b0000000-0000-4000-8000-000000000004', 23, 'Product manager, weekend trekker, and the friend who always knows a good dhaba on the highway.', 'MALE', 'Navi Mumbai, Maharashtra', 'Anant Tyagi', TIMESTAMP '2026-10-07 09:30:00', 'a0000000-0000-4000-8000-000000000004', 'DEPENDS_ON_MOOD', 'TALK_IT_OUT_IMMEDIATELY', 'OPEN_TO_BOTH', 'OPEN_TO_BOTH', 'OCCASIONALLY', 'NON_VEG', 'QUALITY_TIME', 'YES', 'EARLY_BIRD', 'NO', 'I respect a bold opener.', U&'{"id": "weekend", "question": "My weekend reset looks like\2026", "answer": "Kalsubai at sunrise, misal pav on the way back."}', U&'{"id": "admire", "question": "I admire people who\2026", "answer": "Can be the loudest in the room and still listen."}', U&'{"id": "song", "question": "A song that feels like me is\2026", "answer": "Ilahi \2013 Yeh Jawaani Hai Deewani."}', 19.033, 73.0297),
('b0000000-0000-4000-8000-000000000005', 25, 'Architect in Powai. I notice buildings, light and whether you push or pull a door. Bengali, so yes, I have opinions on fish.', 'MALE', 'Mumbai, Maharashtra', 'Siddharth Haldar', TIMESTAMP '2026-10-08 09:30:00', 'a0000000-0000-4000-8000-000000000005', 'CALLS_OVER_TEXTS', 'DEPENDS', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'NON_VEG', 'PHYSICAL_TOUCH', 'NO', 'NIGHT_OWL', 'NO', 'A good conversation beats a perfect line.', '{"id": "misread", "question": "People think I am ___, but I am actually ___", "answer": "Serious, but I am actually just thinking about lunch."}', U&'{"id": "connection_want", "question": "The kind of connection I want is\2026", "answer": "Easy silences and long dinners."}', U&'{"id": "simple_joy", "question": "My simple joy is\2026", "answer": "Monsoon light at 5 pm on old Bandra bungalows."}', 19.1197, 72.9081);  
INSERT INTO "PUBLIC"."PROFILES" VALUES
('b0000000-0000-4000-8000-000000000006', 21, 'Fashion design grad, now styling ad shoots in Andheri. Thrift-store hunter, chronic over-packer, golden retriever energy.', 'FEMALE', 'Bhopal, Madhya Pradesh', 'Mehek Narang', TIMESTAMP '2026-10-09 09:30:00', 'a0000000-0000-4000-8000-000000000006', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'OPEN_TO_BOTH', 'CASUAL_DATING', 'YES', 'NON_VEG', 'GIFTS', 'NO', 'NIGHT_OWL', 'NO', 'If you can make me laugh, you already have my attention.', U&'{"id": "secretly_love", "question": "I secretly love\2026", "answer": "Ironing. It''s therapy. Don''t tell anyone."}', U&'{"id": "green_flag", "question": "A green flag I never ignore is\2026", "answer": "Being nice to my friends before being nice to me."}', U&'{"id": "song", "question": "A song that feels like me is\2026", "answer": "Kala Chashma, unironically."}', 19.1136, 72.8697),
('b0000000-0000-4000-8000-000000000007', 27, 'UX researcher. I ask ''why'' for a living and can''t switch it off. Pune girl, Mumbai weekends.', 'FEMALE', 'Pune, Maharashtra', 'Aditi Kulkarni', TIMESTAMP '2026-10-10 09:30:00', 'a0000000-0000-4000-8000-000000000007', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'VEG', 'QUALITY_TIME', 'YES', 'EARLY_BIRD', 'NO', 'Tell me your most underrated opinion.', U&'{"id": "open_up", "question": "I usually open up when\2026", "answer": "The conversation feels easy and a little silly."}', U&'{"id": "routine", "question": "A routine that keeps me sane is\2026", "answer": "Sunday phone-free mornings at Vetal Tekdi."}', NULL, 18.5204, 73.8567),
('b0000000-0000-4000-8000-000000000008', 26, 'Doctor in residency, so my free time is rare and I spend it wisely: sleep, momos, and good company.', 'FEMALE', 'Mumbai, Maharashtra', 'Ishita Sharma', TIMESTAMP '2026-10-11 09:30:00', 'a0000000-0000-4000-8000-000000000008', 'SLOW_REPLIES', 'TAKE_SPACE_FIRST', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'NO', 'NON_VEG', 'ACTS_OF_SERVICE', 'MAYBE', 'DEPENDS', 'NO', 'Say hi and tell me something small that made you smile today.', U&'{"id": "stressed", "question": "When I am stressed, I\2026", "answer": "Stress-order momos and rewatch Friends."}', U&'{"id": "safe", "question": "A relationship feels safe when\2026", "answer": "I can reply late and nobody keeps score."}', NULL, 19.076, 72.8777),
('b0000000-0000-4000-8000-000000000009', 28, 'Classical dancer turned data analyst. Filter coffee purist. I''ll teach you one Bharatanatyam step if you''re good.', 'FEMALE', 'Mumbai, Maharashtra', 'Naina Iyer', TIMESTAMP '2026-10-12 09:30:00', 'a0000000-0000-4000-8000-000000000009', 'CALLS_OVER_TEXTS', 'DEPENDS', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'NO', 'VEG', 'QUALITY_TIME', 'NO', 'EARLY_BIRD', 'NO', 'A little curiosity goes a long way.', U&'{"id": "comfort", "question": "My comfort habit is\2026", "answer": "Filter coffee at 6 am before the city wakes up."}', U&'{"id": "biggest_thing", "question": "The biggest thing I look for in someone is\2026", "answer": "Gentleness that doesn''t need an audience."}', NULL, 19.0178, 72.8478),
('b0000000-0000-4000-8000-000000000010', 24, 'Marketing at a startup, Thane local, monsoon-trek addict. Looking for someone who can keep up on the trail and in the banter.', 'FEMALE', 'Thane, Maharashtra', 'Riya Deshmukh', TIMESTAMP '2026-10-13 09:30:00', 'a0000000-0000-4000-8000-000000000010', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'OPEN_TO_BOTH', 'OPEN_TO_BOTH', 'OCCASIONALLY', 'NON_VEG', 'QUALITY_TIME', 'NO', 'DEPENDS', 'NO', 'Tell me your most underrated opinion.', U&'{"id": "weekend", "question": "My weekend reset looks like\2026", "answer": "Any trek within 3 hours of Thane, then vada pav."}', U&'{"id": "dealbreaker_prompt", "question": "A dealbreaker for me is\2026", "answer": "Cancelling plans with ''k''."}', NULL, 19.2094, 72.975),
('b0000000-0000-4000-8000-000000000011', 27, 'Lawyer in Lower Parel. I argue for a living, so at home I want peace, plants and pasta.', 'FEMALE', 'Mumbai, Maharashtra', 'Sanya Kapoor', TIMESTAMP '2026-10-14 09:30:00', 'a0000000-0000-4000-8000-000000000011', 'CALLS_OVER_TEXTS', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'NON_VEG', 'WORDS_OF_AFFIRMATION', 'MAYBE', 'NIGHT_OWL', 'NO', 'You can start with a compliment if you mean it.', U&'{"id": "value_people", "question": "I value people who\2026", "answer": "Say what they mean the first time."}', U&'{"id": "talk_about", "question": "A random thing I could talk about for hours is\2026", "answer": "True crime podcasts and why they''re all slightly wrong."}', NULL, 18.9967, 72.8258);          
