('b0000000-0000-4000-8000-000000000019', 28, 'Investment banker who actually likes his job (rare). Gujju, so food is love. Salsa classes on Thursdays.', 'MALE', 'Mumbai, Maharashtra', 'Rohan Mehta', TIMESTAMP '2026-10-22 09:30:00', 'a0000000-0000-4000-8000-000000000019', 'CALLS_OVER_TEXTS', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'VEG', 'GIFTS', 'NO', 'EARLY_BIRD', 'NO', 'Start sweet, start funny, start however you like.', U&'{"id": "feel_loved", "question": "The way I feel loved is\2026", "answer": "Someone saving me the last piece of dhokla."}', NULL, NULL, 19.064, 72.835),
('b0000000-0000-4000-8000-000000000020', 27, 'Indie musician + sound engineer in Versova. I''ll make you a playlist before our second date.', 'MALE', 'Mumbai, Maharashtra', 'Kabir Malhotra', TIMESTAMP '2026-10-23 09:30:00', 'a0000000-0000-4000-8000-000000000020', 'DEPENDS_ON_MOOD', 'DEPENDS', 'OPEN_TO_BOTH', 'CASUAL_DATING', 'YES', 'NON_VEG', 'QUALITY_TIME', 'NO', 'NIGHT_OWL', 'OCCASIONALLY', 'Come with a good joke or a better playlist.', U&'{"id": "song", "question": "A song that feels like me is\2026", "answer": "Choo Lo \2013 The Local Train."}', NULL, NULL, 19.1076, 72.8263),
('b0000000-0000-4000-8000-000000000021', 29, 'Marine engineer, home for six months, then back to sea. Make them count? Sailing stories included.', 'MALE', 'Navi Mumbai, Maharashtra', 'Arjun Nair', TIMESTAMP '2026-10-04 09:30:00', 'a0000000-0000-4000-8000-000000000021', 'SLOW_REPLIES', 'TAKE_SPACE_FIRST', 'OPEN_TO_BOTH', 'OPEN_TO_BOTH', 'OCCASIONALLY', 'NON_VEG', 'PHYSICAL_TOUCH', 'YES', 'EARLY_BIRD', 'NO', 'A little curiosity goes a long way.', '{"id": "misread", "question": "People think I am ___, but I am actually ___", "answer": "Quiet, but I am actually just buffering."}', NULL, NULL, 19.076, 73.001),
('b0000000-0000-4000-8000-000000000022', 26, 'Startup founder (edtech), occasional stand-up open mics. I''ll overshare my pitch deck. You''ve been warned.', 'MALE', 'Thane, Maharashtra', 'Vivaan Shah', TIMESTAMP '2026-10-05 09:30:00', 'a0000000-0000-4000-8000-000000000022', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'SHORT_TERM', 'CASUAL_DATING', 'OCCASIONALLY', 'NON_VEG', 'WORDS_OF_AFFIRMATION', 'NO', 'NIGHT_OWL', 'NO', 'If you can make me laugh, you already have my attention.', U&'{"id": "getting_better", "question": "Something I am trying to get better at is\2026", "answer": "Leaving work at work. Day 3. Going badly."}', NULL, NULL, 19.244, 72.969),
('b0000000-0000-4000-8000-000000000023', 30, 'Chef at a Bandra bistro. I cook all week, so on dates I want someone else to pick the place. Your call.', 'MALE', 'Mumbai, Maharashtra', 'Karan Bhatia', TIMESTAMP '2026-10-06 09:30:00', 'a0000000-0000-4000-8000-000000000023', 'CALLS_OVER_TEXTS', 'DEPENDS', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'NON_VEG', 'ACTS_OF_SERVICE', 'NO', 'NIGHT_OWL', 'NO', 'Sell me your favourite Mumbai food spot in one line.', U&'{"id": "simple_joy", "question": "My simple joy is\2026", "answer": "Feeding people who close their eyes on the first bite."}', NULL, NULL, 19.0596, 72.8358),
('b0000000-0000-4000-8000-000000000024', 27, 'Data scientist in Pune. Cricket nerd, quiz-night regular, and fairly decent at cooking rajma chawal.', 'MALE', 'Pune, Maharashtra', 'Aman Gupta', TIMESTAMP '2026-10-07 09:30:00', 'a0000000-0000-4000-8000-000000000024', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'NO', 'VEG', 'QUALITY_TIME', 'YES', 'EARLY_BIRD', 'NO', 'Tell me your most underrated opinion.', U&'{"id": "talk_about", "question": "A random thing I could talk about for hours is\2026", "answer": "Why Test cricket is the greatest sport ever invented."}', NULL, NULL, 18.5679, 73.9143),
('b0000000-0000-4000-8000-000000000025', 25, 'Physiotherapist and gym coach. I''ll fix your posture before dessert. Thane born, Thane proud.', 'MALE', 'Thane, Maharashtra', 'Yash Patil', TIMESTAMP '2026-10-08 09:30:00', 'a0000000-0000-4000-8000-000000000025', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'OPEN_TO_BOTH', 'OPEN_TO_BOTH', 'NO', 'NON_VEG', 'PHYSICAL_TOUCH', 'NO', 'EARLY_BIRD', 'NO', 'I respect a bold opener.', U&'{"id": "routine", "question": "A routine that keeps me sane is\2026", "answer": "6 am at Upvan lake before anyone else is awake."}', NULL, NULL, 19.201, 72.964);        
INSERT INTO "PUBLIC"."PROFILES" VALUES
('b0000000-0000-4000-8000-000000000026', 28, 'Film editor. I cut trailers for a living, so I''ll make our first date look way better in hindsight.', 'MALE', 'Mumbai, Maharashtra', 'Dev Chatterjee', TIMESTAMP '2026-10-09 09:30:00', 'a0000000-0000-4000-8000-000000000026', 'DEPENDS_ON_MOOD', 'TAKE_SPACE_FIRST', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'NON_VEG', 'QUALITY_TIME', 'MAYBE', 'NIGHT_OWL', 'NO', 'A good conversation beats a perfect line.', U&'{"id": "secretly_love", "question": "I secretly love\2026", "answer": "Bad 2000s Bollywood remakes. For research. Mostly."}', NULL, NULL, 19.1726, 72.9425),
('b0000000-0000-4000-8000-000000000027', 26, 'Consultant who lives out of a carry-on. Back in Mumbai most weekends. Looking for a reason to stay put.', 'MALE', 'Mumbai, Maharashtra', 'Ishaan Kapoor', TIMESTAMP '2026-10-10 09:30:00', 'a0000000-0000-4000-8000-000000000027', 'TEXT_A_LOT', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'OCCASIONALLY', 'NON_VEG', 'WORDS_OF_AFFIRMATION', 'YES', 'DEPENDS', 'NO', 'Say hi and tell me something small that made you smile today.', U&'{"id": "connection_want", "question": "The kind of connection I want is\2026", "answer": "Someone I''m excited to fly home to."}', NULL, NULL, 19.1197, 72.8464),
('b0000000-0000-4000-8000-000000000028', 29, 'Pilot. Yes, I''ll tell you the turbulence story. No, I won''t tell you which airline.', 'MALE', 'Navi Mumbai, Maharashtra', 'Manav Joshi', TIMESTAMP '2026-10-11 09:30:00', 'a0000000-0000-4000-8000-000000000028', 'SLOW_REPLIES', 'DEPENDS', 'OPEN_TO_BOTH', 'CASUAL_DATING', 'OCCASIONALLY', 'NON_VEG', 'QUALITY_TIME', 'YES', 'DEPENDS', 'NO', 'A little curiosity goes a long way.', U&'{"id": "comfort", "question": "My comfort habit is\2026", "answer": "Window seat, even when I''m the one flying."}', NULL, NULL, 19.0473, 73.0699),
('b0000000-0000-4000-8000-000000000029', 27, 'Biotech researcher at IIT-B. Plants, podcasts and probably too many spreadsheets about plants.', 'MALE', 'Mumbai, Maharashtra', 'Nikhil Rao', TIMESTAMP '2026-10-12 09:30:00', 'a0000000-0000-4000-8000-000000000029', 'CALLS_OVER_TEXTS', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'NO', 'VEG', 'ACTS_OF_SERVICE', 'MAYBE', 'EARLY_BIRD', 'NO', 'Tell me your most underrated opinion.', U&'{"id": "value_people", "question": "I value people who\2026", "answer": "Get excited about things, even nerdy ones."}', NULL, NULL, 19.033, 72.857),
('b0000000-0000-4000-8000-000000000030', 28, 'Runs his family''s attar business near Crawford Market and a small travel blog on the side. Old Mumbai is my favourite person.', 'MALE', 'Mumbai, Maharashtra', 'Faizan Sheikh', TIMESTAMP '2026-10-13 09:30:00', 'a0000000-0000-4000-8000-000000000030', 'CALLS_OVER_TEXTS', 'TALK_IT_OUT_IMMEDIATELY', 'LONG_TERM', 'SERIOUS_RELATIONSHIP', 'NO', 'NON_VEG', 'GIFTS', 'NO', 'NIGHT_OWL', 'NO', 'Sell me your favourite Mumbai food spot in one line.', U&'{"id": "talk_about", "question": "A random thing I could talk about for hours is\2026", "answer": "The stories behind every old building in Fort."}', NULL, NULL, 18.9543, 72.831);
