INSERT INTO "PUBLIC"."MESSAGES" VALUES
('90000000-0000-4000-8000-000000000001', 'Okay, I need to know. What''s the correct chai order, according to you?', TIMESTAMP '2026-10-18 19:30:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000002', 'Cutting, extra adrak, no elaichi. Elaichi is for people who are scared of flavour.', TIMESTAMP '2026-10-18 19:55:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000003', 'That''s a bold stance. I''m an elaichi guy. Is this over already?', TIMESTAMP '2026-10-18 20:00:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000004', 'I''ll allow it. Once. Because your Mumbai local opinion was correct.', TIMESTAMP '2026-10-18 20:20:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000005', 'It IS the best-designed system in India. 7.5 million people a day and it mostly works.', TIMESTAMP '2026-10-19 16:30:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000006', U&'Mostly is carrying a lot of weight in that sentence \+01f602', TIMESTAMP '2026-10-19 16:50:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000007', 'Western line at 9 am is not a system, it''s a contact sport.', TIMESTAMP '2026-10-19 16:51:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000008', 'Fair. Central line gang can''t relate, we just suffer quietly.', TIMESTAMP '2026-10-19 17:20:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000009', 'Random question: best thing you ate this week?', TIMESTAMP '2026-10-21 11:30:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000010', 'Misal at Mamledar in Thane. Spicy enough that I questioned my life choices.', TIMESTAMP '2026-10-21 12:10:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000011', 'Okay that''s going on my list. Bandra counter-offer: the kheema pav at Lucky.', TIMESTAMP '2026-10-21 12:30:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000012', U&'Deal. Food swap then \2014 I come to Bandra once, you come to Thane once?', TIMESTAMP '2026-10-22 18:10:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000013', 'Look at you, planning. I like it.', TIMESTAMP '2026-10-22 18:30:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000014', 'Saturday evening work for the Bandra leg? Carter Road chai first?', TIMESTAMP '2026-10-23 14:50:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000015', 'Saturday works! Sea will be dramatic, I''ve checked the forecast.', TIMESTAMP '2026-10-24 08:40:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000016', 'Also you''re buying. Elaichi tax.', TIMESTAMP '2026-10-24 08:42:00', 'f0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000017', 'Your opening line made me think for 10 minutes. Underrated opinion: pineapple on pizza is fine.', TIMESTAMP '2026-10-20 18:10:00', 'f0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000006'),
('90000000-0000-4000-8000-000000000018', 'Respect. Mine: Thane has better food than half of Bandra.', TIMESTAMP '2026-10-20 19:00:00', 'f0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000019', 'Ohhh that''s fighting talk. I''m going to need evidence.', TIMESTAMP '2026-10-20 19:10:00', 'f0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000006');       
INSERT INTO "PUBLIC"."MESSAGES" VALUES
('90000000-0000-4000-8000-000000000020', 'Evidence tour can be arranged. Vada pav, misal, and Gokul''s ice cream.', TIMESTAMP '2026-10-20 19:50:00', 'f0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000021', U&'Sorry, shoot week, I''ve been dead. Still on for the evidence tour though \+01f602', TIMESTAMP '2026-10-21 13:10:00', 'f0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000006'),
('90000000-0000-4000-8000-000000000022', U&'No worries! Let me know when you''re free \2014 the vada pav isn''t going anywhere.', TIMESTAMP '2026-10-22 20:00:00', 'f0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000023', 'Hi! Fellow Thane person. Which side are you on, lake side or station side?', TIMESTAMP '2026-10-21 14:50:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000003'),
('90000000-0000-4000-8000-000000000024', 'Upvan lake side. You?', TIMESTAMP '2026-10-21 15:10:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000025', 'Ghodbunder Road. Practically neighbours, then.', TIMESTAMP '2026-10-21 15:20:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000003'),
('90000000-0000-4000-8000-000000000026', 'How''s the sourdough situation? Your profile said it was winning.', TIMESTAMP '2026-10-21 16:30:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000027', 'It''s still winning. Yesterday''s loaf could be used as a weapon.', TIMESTAMP '2026-10-21 16:40:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000003'),
('90000000-0000-4000-8000-000000000028', 'I volunteer as a taste tester. Low standards, high enthusiasm.', TIMESTAMP '2026-10-22 11:30:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000029', 'Okay, coffee this weekend? There''s a nice place near Hiranandani Estate.', TIMESTAMP '2026-10-23 16:30:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000003'),
('90000000-0000-4000-8000-000000000030', 'Sunday morning works for me. 10ish?', TIMESTAMP '2026-10-23 17:20:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000031', U&'Perfect, Sunday 10. I''ll bring a slice of the weapon loaf \+01f35e', TIMESTAMP '2026-10-24 07:30:00', 'f0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000003'),
('90000000-0000-4000-8000-000000000032', 'Biryani debate time: Hyderabadi or Lucknowi?', TIMESTAMP '2026-10-12 16:30:00', 'f0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000013'),
('90000000-0000-4000-8000-000000000033', 'Hyderabadi. Is that the right answer for my survival?', TIMESTAMP '2026-10-12 17:30:00', 'f0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000034', 'Correct answer. You may continue.', TIMESTAMP '2026-10-12 17:40:00', 'f0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000013'),
('90000000-0000-4000-8000-000000000035', 'How''s the half-marathon training going?', TIMESTAMP '2026-10-13 13:10:00', 'f0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000001'),
('90000000-0000-4000-8000-000000000036', 'Slow but steady! Sorry, work''s been crazy this week.', TIMESTAMP '2026-10-15 18:10:00', 'f0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000013'),
('90000000-0000-4000-8000-000000000037', 'Late-night Bade Miya with the windows down is elite. What''s your order?', TIMESTAMP '2026-10-19 13:10:00', 'f0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000004'),
('90000000-0000-4000-8000-000000000038', 'Chicken seekh and baida roti, no compromises. Yours?', TIMESTAMP '2026-10-19 13:30:00', 'f0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000016');               
INSERT INTO "PUBLIC"."MESSAGES" VALUES
('90000000-0000-4000-8000-000000000039', 'Same, plus a cold drink I regret at 2 am.', TIMESTAMP '2026-10-19 13:40:00', 'f0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000004'),
('90000000-0000-4000-8000-000000000040', 'Okay I like you. Food tour sometime?', TIMESTAMP '2026-10-20 19:50:00', 'f0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000016'),
('90000000-0000-4000-8000-000000000041', 'Only if you let me take you on a trek after. Balance.', TIMESTAMP '2026-10-20 20:30:00', 'f0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000004'),
('90000000-0000-4000-8000-000000000042', 'A trekker who knows highway dhabas? You''re basically a tourism department.', TIMESTAMP '2026-10-21 16:30:00', 'f0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000012'),
('90000000-0000-4000-8000-000000000043', 'Happy to be of service. Where have you trekked?', TIMESTAMP '2026-10-21 16:50:00', 'f0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000004'),
('90000000-0000-4000-8000-000000000044', 'Only Rajmachi, and I complained the whole way.', TIMESTAMP '2026-10-21 18:10:00', 'f0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000012'),
('90000000-0000-4000-8000-000000000045', 'Rajmachi is a great start. Harishchandragad next?', TIMESTAMP '2026-10-22 19:50:00', 'f0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000004'),
('90000000-0000-4000-8000-000000000046', 'Only if there''s a good dhaba at the end. And you carry my bag halfway.', TIMESTAMP '2026-10-24 04:30:00', 'f0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000012'),
('90000000-0000-4000-8000-000000000047', 'Peace, plants and pasta is a strong life philosophy.', TIMESTAMP '2026-10-17 14:50:00', 'f0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000005'),
('90000000-0000-4000-8000-000000000048', 'It''s the only thing keeping me sane between hearings.', TIMESTAMP '2026-10-17 15:10:00', 'f0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000011'),
('90000000-0000-4000-8000-000000000049', 'I''m decent at aglio olio. Can''t argue to save my life though.', TIMESTAMP '2026-10-17 16:30:00', 'f0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000005'),
('90000000-0000-4000-8000-000000000050', 'Perfect. I''ll do the arguing, you do the cooking.', TIMESTAMP '2026-10-18 18:10:00', 'f0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000011'),
('90000000-0000-4000-8000-000000000051', 'Sounds like a fair contract. Do I need to sign anything?', TIMESTAMP '2026-10-18 19:50:00', 'f0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000005'),
('90000000-0000-4000-8000-000000000052', 'Haha, verbal agreement is binding. Friday?', TIMESTAMP '2026-10-19 20:40:00', 'f0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000011'),
('90000000-0000-4000-8000-000000000053', 'Friday it is.', TIMESTAMP '2026-10-19 21:10:00', 'f0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000005'),
('90000000-0000-4000-8000-000000000054', 'An architect who notices doors. Which building in Mumbai do you love most?', TIMESTAMP '2026-10-20 18:10:00', 'f0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000018'),
('90000000-0000-4000-8000-000000000055', U&'The Flora Fountain buildings at sunset. Also the old Irani caf\00e9s.', TIMESTAMP '2026-10-20 18:30:00', 'f0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000005'),
('90000000-0000-4000-8000-000000000056', U&'I wrote a piece on the Irani caf\00e9s last year! Kyani''s is my comfort place.', TIMESTAMP '2026-10-20 18:40:00', 'f0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000018'),
('90000000-0000-4000-8000-000000000057', 'Kyani''s bun maska and a long chat? I''d like that.', TIMESTAMP '2026-10-21 19:50:00', 'f0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000005'),
('90000000-0000-4000-8000-000000000058', 'Let''s do it. Next weekend, I''m on night shifts till then.', TIMESTAMP '2026-10-24 06:10:00', 'f0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000018');            
INSERT INTO "PUBLIC"."MESSAGES" VALUES
('90000000-0000-4000-8000-000000000059', U&'Salsa on Thursdays and playlists \2014 we might be compatible.', TIMESTAMP '2026-10-16 13:10:00', 'f0000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000019'),
('90000000-0000-4000-8000-000000000060', 'Do you actually dance or just stand there and count?', TIMESTAMP '2026-10-16 14:00:00', 'f0000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000061', 'I count with conviction.', TIMESTAMP '2026-10-16 14:10:00', 'f0000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000019'),
('90000000-0000-4000-8000-000000000062', 'Haha okay that''s honest. Nice chatting, Rohan!', TIMESTAMP '2026-10-17 18:10:00', 'f0000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000002'),
('90000000-0000-4000-8000-000000000063', U&'A CA who reads thrillers \2014 favourite this year?', TIMESTAMP '2026-10-18 16:30:00', 'f0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000024'),
('90000000-0000-4000-8000-000000000064', 'The Silent Patient. Twist got me.', TIMESTAMP '2026-10-18 17:20:00', 'f0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000003'),
('90000000-0000-4000-8000-000000000065', 'Same! I''m on Gone Girl now.', TIMESTAMP '2026-10-18 17:30:00', 'f0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000024'),
('90000000-0000-4000-8000-000000000066', 'Don''t trust anyone in that book.', TIMESTAMP '2026-10-19 19:50:00', 'f0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000003'),
('90000000-0000-4000-8000-000000000067', 'Stress-order momos is valid. But have you had a chef make you momos?', TIMESTAMP '2026-10-19 18:10:00', 'f0000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000023'),
('90000000-0000-4000-8000-000000000068', 'Is that an offer? Because I''m on call till Sunday.', TIMESTAMP '2026-10-19 19:50:00', 'f0000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000008'),
('90000000-0000-4000-8000-000000000069', 'Monday then. Pork or veg?', TIMESTAMP '2026-10-20 16:30:00', 'f0000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000023'),
('90000000-0000-4000-8000-000000000070', U&'Pork, obviously. Monday after my shift \+01f95f', TIMESTAMP '2026-10-23 23:30:00', 'f0000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000008'),
('90000000-0000-4000-8000-000000000071', '23 plants?? Do they all have names?', TIMESTAMP '2026-10-20 14:50:00', 'f0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000025'),
('90000000-0000-4000-8000-000000000072', 'Every single one. The money plant is Rekha.', TIMESTAMP '2026-10-20 15:40:00', 'f0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000014'),
('90000000-0000-4000-8000-000000000073', 'Iconic. Can I meet Rekha?', TIMESTAMP '2026-10-20 15:50:00', 'f0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000025'),
('90000000-0000-4000-8000-000000000074', 'Only if you bring her a new pot.', TIMESTAMP '2026-10-21 19:50:00', 'f0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000014'),
('90000000-0000-4000-8000-000000000075', 'Done. Upvan lake walk first?', TIMESTAMP '2026-10-21 20:10:00', 'f0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000025'),
('90000000-0000-4000-8000-000000000076', U&'Saturday 6 pm \+01f33f', TIMESTAMP '2026-10-21 20:30:00', 'f0000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000014'),
('90000000-0000-4000-8000-000000000077', U&'Mountains and museums \2014 which one this month?', TIMESTAMP '2026-10-15 16:30:00', 'f0000000-0000-4000-8000-000000000017', 'a0000000-0000-4000-8000-000000000028'),
('90000000-0000-4000-8000-000000000078', 'Mountains. Thinking Sandhan Valley.', TIMESTAMP '2026-10-16 18:10:00', 'f0000000-0000-4000-8000-000000000017', 'a0000000-0000-4000-8000-000000000015'),
('90000000-0000-4000-8000-000000000079', 'Great choice. I''ll be flying, so send photos?', TIMESTAMP '2026-10-16 19:50:00', 'f0000000-0000-4000-8000-000000000017', 'a0000000-0000-4000-8000-000000000028');          
INSERT INTO "PUBLIC"."MESSAGES" VALUES
('90000000-0000-4000-8000-000000000080', 'Strong lassi opinions? Go on.', TIMESTAMP '2026-10-18 13:10:00', 'f0000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000020'),
('90000000-0000-4000-8000-000000000081', 'Salted. Sweet lassi is a dessert pretending to be a drink.', TIMESTAMP '2026-10-18 13:30:00', 'f0000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000016'),
('90000000-0000-4000-8000-000000000082', 'Making you a playlist called ''Salted''.', TIMESTAMP '2026-10-18 14:50:00', 'f0000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000020'),
('90000000-0000-4000-8000-000000000083', 'Okay that''s cute, I''ll allow it.', TIMESTAMP '2026-10-19 18:10:00', 'f0000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000016'),
('90000000-0000-4000-8000-000000000084', U&'Filter coffee purist \2014 decoction or instant?', TIMESTAMP '2026-10-14 16:30:00', 'f0000000-0000-4000-8000-000000000021', 'a0000000-0000-4000-8000-000000000029'),
('90000000-0000-4000-8000-000000000085', 'Decoction. Brass filter. Inherited from my grandmother.', TIMESTAMP '2026-10-14 18:10:00', 'f0000000-0000-4000-8000-000000000021', 'a0000000-0000-4000-8000-000000000009'),
('90000000-0000-4000-8000-000000000086', 'That''s a family heirloom, not a coffee maker.', TIMESTAMP '2026-10-14 18:30:00', 'f0000000-0000-4000-8000-000000000021', 'a0000000-0000-4000-8000-000000000029'),
('90000000-0000-4000-8000-000000000087', 'Exactly. Respect it.', TIMESTAMP '2026-10-15 19:50:00', 'f0000000-0000-4000-8000-000000000021', 'a0000000-0000-4000-8000-000000000009'),
('90000000-0000-4000-8000-000000000088', U&'Coconut in everything \2014 even coffee?', TIMESTAMP '2026-10-17 16:30:00', 'f0000000-0000-4000-8000-000000000023', 'a0000000-0000-4000-8000-000000000021'),
('90000000-0000-4000-8000-000000000089', 'Coconut cold brew is underrated. Fight me.', TIMESTAMP '2026-10-17 17:20:00', 'f0000000-0000-4000-8000-000000000023', 'a0000000-0000-4000-8000-000000000014'),
('90000000-0000-4000-8000-000000000090', 'No fight. I''ll try it.', TIMESTAMP '2026-10-18 19:50:00', 'f0000000-0000-4000-8000-000000000023', 'a0000000-0000-4000-8000-000000000021'),
('90000000-0000-4000-8000-000000000091', 'Half-marathon in December? Which one?', TIMESTAMP '2026-10-19 16:30:00', 'f0000000-0000-4000-8000-000000000024', 'a0000000-0000-4000-8000-000000000027'),
('90000000-0000-4000-8000-000000000092', 'Navi Mumbai one! You run?', TIMESTAMP '2026-10-19 17:20:00', 'f0000000-0000-4000-8000-000000000024', 'a0000000-0000-4000-8000-000000000013'),
('90000000-0000-4000-8000-000000000093', 'Only to catch flights. But I''ll cheer from km 15.', TIMESTAMP '2026-10-20 18:10:00', 'f0000000-0000-4000-8000-000000000024', 'a0000000-0000-4000-8000-000000000027'),
('90000000-0000-4000-8000-000000000094', U&'Holding you to that. Bring bananas \+01f34c', TIMESTAMP '2026-10-23 12:30:00', 'f0000000-0000-4000-8000-000000000024', 'a0000000-0000-4000-8000-000000000013');    
